using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckBogSnorkelling {
public enum BogState{Waiting,Racing,Stalled,Penalty,Finished,DNF,Inactive}
public sealed class BogRacer:MonoBehaviour {
 public BogMatch match;public SportsEventTruck truck;public Transform intake;public ParticleSystem bubbles,sediment,splash;public AudioLowPassFilter filter;public BogState State{get;private set;}public float Air{get;private set;}=BogCourse.AirSeconds;public int Checkpoint{get;private set;}public int Recoveries{get;private set;}public float FinishTime{get;private set;}=float.PositiveInfinity;public bool Submerged{get;private set;}public bool IntakeOpen{get;private set;}public bool Diving{get;private set;}public float PenaltyRemaining{get;private set;}public Vector3 SafePosition{get;private set;}
 Vector3 previous;float stateAge,stuck,nextSplash;bool wasWet;readonly RaycastHit[] obstruction=new RaycastHit[24];readonly Collider[] intakeOverlaps=new Collider[24];
 public void Prepare(bool active){State=active?BogState.Waiting:BogState.Inactive;Checkpoint=Recoveries=0;Air=BogCourse.AirSeconds;FinishTime=float.PositiveInfinity;PenaltyRemaining=stateAge=stuck=0;SafePosition=match.course.Spawn(truck.slot);truck.visuals.gameObject.SetActive(active);truck.Prepare(SafePosition,Quaternion.identity);truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=active;previous=SafePosition;ClearEffects();}
 public void Release(){if(State!=BogState.Waiting)return;State=BogState.Racing;truck.body.isKinematic=false;truck.Power(true);}
 public Vector3 IntakePosition=>truck.body.position+truck.body.rotation*Vector3.Scale(intake.localPosition,truck.transform.lossyScale);public bool ClearIntake(){var from=IntakePosition;int overlaps=Physics.OverlapSphereNonAlloc(from,.09f,intakeOverlaps,~0,QueryTriggerInteraction.Ignore);var all=overlaps==intakeOverlaps.Length?Physics.OverlapSphere(from,.09f,~0,QueryTriggerInteraction.Ignore):null;for(int i=0;i<(all!=null?all.Length:overlaps);i++){var collider=all!=null?all[i]:intakeOverlaps[i];if(collider.attachedRigidbody!=truck.body)return false;}int n=Physics.SphereCastNonAlloc(from,.09f,Vector3.up,obstruction,.5f,~0,QueryTriggerInteraction.Ignore);var hits=n==obstruction.Length?Physics.SphereCastAll(from,.09f,Vector3.up,.5f,~0,QueryTriggerInteraction.Ignore):null;int count=hits!=null?hits.Length:n;for(int i=0;i<count;i++){var h=hits!=null?hits[i]:obstruction[i];if(h.rigidbody!=truck.body)return false;}return true;}
 public void Step(Vector2 drive,bool dive,float dt){if(State==BogState.Waiting||State==BogState.Inactive||State==BogState.Finished||State==BogState.DNF)return;stateAge+=dt;if(State==BogState.Penalty){PenaltyRemaining=Mathf.Max(0,5-stateAge);if(stateAge>=5){State=BogState.Racing;truck.body.isKinematic=false;truck.body.detectCollisions=true;truck.Power(true);Air=BogCourse.AirSeconds;stateAge=0;}return;}
 var body=truck.body;float water=match.course.WaterHeight;var position=body.position;Submerged=IntakePosition.y<water+.08f;IntakeOpen=!Submerged&&ClearIntake();Air=Mathf.Clamp(Air+(IntakeOpen?4:-1)*dt,0,BogCourse.AirSeconds);float bottom=position.y+truck.shape.center.y-truck.shape.size.y*.5f;float fraction=Mathf.Clamp01((water-bottom)/Mathf.Max(.3f,truck.shape.size.y));Diving=dive&&fraction>.15f;if(fraction>0){body.AddForce(Vector3.up*(Physics.gravity.magnitude*1.06f*fraction-(Diving?Physics.gravity.magnitude*.9f:0)),ForceMode.Acceleration);body.AddForce(-body.linearVelocity*(.25f*fraction),ForceMode.Acceleration);var righting=Vector3.Cross(body.rotation*Vector3.up,Vector3.up);body.AddTorque(righting*1.4f-body.angularVelocity*.35f,ForceMode.Acceleration);if((!truck.Grounded||fraction>.4f)&&State==BogState.Racing){var forward=Vector3.ProjectOnPlane(body.rotation*Vector3.forward,Vector3.up).normalized;if(body.linearVelocity.magnitude<8||Vector3.Dot(body.linearVelocity,forward)*drive.y<0)body.AddForce(forward*drive.y*2*fraction,ForceMode.Acceleration);body.AddTorque(Vector3.up*drive.x*.32f,ForceMode.Acceleration);}}
 if(State==BogState.Stalled){truck.Power(false);if(stateAge>2)Recover("AIR DEPLETED");return;}if(Air<=0){State=BogState.Stalled;stateAge=0;truck.Power(false);match.feedback.Play(4,0,true);return;}truck.grip=.8f*match.course.weather.Grip;truck.TickDrive(drive);
 while(Checkpoint<match.course.checkpoints.Length&&previous.z<match.course.checkpoints[Checkpoint]&&position.z>=match.course.checkpoints[Checkpoint]){float z=match.course.checkpoints[Checkpoint];float x=Mathf.Lerp(previous.x,position.x,Mathf.InverseLerp(previous.z,position.z,z));if(Mathf.Abs(x-BogCourse.Center(z))>24)break;Checkpoint++;if(IntakeOpen&&match.course.Safe(z))SafePosition=match.course.Surface(new Vector3(x,0,z))+Vector3.up*.55f;}
 if(Checkpoint==match.course.checkpoints.Length&&previous.z<BogCourse.Finish&&position.z>=BogCourse.Finish&&Mathf.Abs(position.x-BogCourse.Center(BogCourse.Finish))<24){State=BogState.Finished;FinishTime=match.Clock-dt+Mathf.InverseLerp(previous.z,position.z,BogCourse.Finish)*dt;truck.Power(false);match.feedback.Play(5,0,true);return;}previous=position;stuck=body.linearVelocity.sqrMagnitude<.04f&&Mathf.Abs(drive.y)>.3f?stuck+dt:0;if(position.y< -12||Mathf.Abs(position.x)>64||position.z< -10||stuck>12)Recover("STRANDED");}
 public void Recover(string reason){if(State==BogState.Finished||State==BogState.Inactive||State==BogState.DNF)return;Recoveries++;if(Recoveries>3){Fail();return;}State=BogState.Penalty;stateAge=stuck=0;PenaltyRemaining=5;truck.Park(SafePosition);truck.body.detectCollisions=true;previous=SafePosition;Debug.Log("BOG_RECOVERY slot="+truck.slot+" reason="+reason+" lastSafe="+SafePosition+" checkpoint="+Checkpoint);}
 public void Fail(){if(State==BogState.Finished||State==BogState.Inactive)return;State=BogState.DNF;truck.Park(truck.body.position);}
 public void Effects(){if(truck==null)return;if(filter!=null)filter.cutoffFrequency=Submerged?750:22000;bool wet=match.Live&&State==BogState.Racing&&Submerged;if(wet&&!bubbles.isPlaying)bubbles.Play();if(wet!=wasWet&&Time.time>=nextSplash&&match.Live){splash.transform.position=new Vector3(truck.body.position.x,match.course.WaterHeight,truck.body.position.z);splash.Play();match.feedback.Play(1,3);nextSplash=Time.time+.6f;}wasWet=wet;var emission=bubbles.emission;emission.enabled=wet;bubbles.transform.position=IntakePosition;bool stirred=wet&&truck.Grounded&&truck.body.linearVelocity.sqrMagnitude>1;if(stirred&&!sediment.isPlaying)sediment.Play();emission=sediment.emission;emission.enabled=stirred;sediment.transform.position=truck.body.position-Vector3.up*.25f;}
 public void ClearEffects(){foreach(var p in new[]{bubbles,sediment,splash})if(p!=null)p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}void OnDisable(){ClearEffects();}
}
}
